package com.mcnex.conversation;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class NavigationProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private boolean contains(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),text))return true;}return false;}
 public void onStart(){JSONObject report=new JSONObject();try{MainActivity a=(MainActivity)startActivitySync(new android.content.Intent(getTargetContext(),MainActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->{for(int tab=0;tab<3;tab++){a.navigate(tab);String expected=new String[]{"회의 기록","휴대폰 회의","회의록 설정"}[tab];if(!contains(a.findViewById(android.R.id.content),expected))throw new IllegalStateException("Missing tab "+tab);}a.navigate(1);if(!contains(a.findViewById(android.R.id.content),"AI Tip"))throw new IllegalStateException("Missing AI Tip");});runOnMainSync(()->{a.navigate(1);long t=SystemClock.uptimeMillis();a.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,900,260,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+60,MotionEvent.ACTION_MOVE,100,260,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+120,MotionEvent.ACTION_UP,100,260,0));if(!contains(a.findViewById(android.R.id.content),"회의록 설정"))throw new IllegalStateException("Page swipe failed");});int[] invoked={0,0};SwipeMeetingCard[] swipe={null};runOnMainSync(()->{a.screen();LinearLayout page=(LinearLayout)((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);TextView card=a.text("스와이프 동작 시험 · 실제 회의 아님",18,0xff11302a,true);card.setPadding(20,40,20,40);swipe[0]=new SwipeMeetingCard(a,card,()->{},()->invoked[0]++,()->invoked[1]++);swipe[0].bind(()->invoked[0]++,()->invoked[1]++);page.addView(swipe[0],new LinearLayout.LayoutParams(-1,180));});Thread.sleep(600);for(int direction:new int[]{-1,1}){runOnMainSync(()->{SwipeMeetingCard v=swipe[0];float start=v.getWidth()/2f;long time=SystemClock.uptimeMillis();v.dispatchTouchEvent(MotionEvent.obtain(time,time,MotionEvent.ACTION_DOWN,start,60,0));v.dispatchTouchEvent(MotionEvent.obtain(time,time+50,MotionEvent.ACTION_MOVE,start+direction*v.getWidth()*.75f,60,0));v.dispatchTouchEvent(MotionEvent.obtain(time,time+100,MotionEvent.ACTION_UP,start+direction*v.getWidth()*.75f,60,0));});Thread.sleep(350);runOnMainSync(()->{((ImageButton)swipe[0].getTag()).performClick();swipe[0].getChildAt(1).performClick();});Thread.sleep(350);}if(invoked[0]!=1||invoked[1]!=1)throw new IllegalStateException("Swipe actions failed "+invoked[0]+"/"+invoked[1]);report.put("pageSwipe",true).put("tabs",true).put("phoneTip",true).put("swipeDeleteCallback",invoked[0]).put("swipeShareCallback",invoked[1]).put("ok",true);runOnMainSync(()->a.navigate(0));Thread.sleep(2000);}catch(Throwable e){try{report.put("ok",false).put("error",e.toString());}catch(Exception ignored){}}try(java.io.FileOutputStream f=getTargetContext().openFileOutput("navigation-probe.json",0)){f.write(report.toString().getBytes("UTF-8"));}catch(Exception ignored){}Bundle b=new Bundle();b.putString("report",report.toString());finish(report.optBoolean("ok")?-1:0,b);}
}
